"""
run_multiseed_2labs.py
========================
Runs evaluate_approximation.py multiple times, with different run_seeds,
for the 2-lab instance, then aggregates policy-agreement / value-gap
numbers (mean +/- std), plus theta convergence plots (per-seed and
combined-across-seeds).

CAPACITY: K_CAPACITY=2 (up from 1). At K=1 each inventory cell could
only be empty or hold a single kit -- unrealistically tight, and
flagged for correction. Raising it to 2 grows the state space
substantially: verified directly, state enumeration now produces 2187
states (up from 192, an 11x increase; 6 inventory cells -- 1 depot + 2
labs, x 2 age classes -- each taking 3 values instead of 2). The exact
LP itself (2187 states x 3 actions = 6561 constraints) was solved
directly as part of this verification and completed in about 2
seconds, so the LP side of the pipeline is not the concern.

PSMD training time is the real unknown here. It scales with the
iteration budget T rather than with |S| directly, so it should NOT
grow 11x just because the state space did -- but the per-checkpoint
UB-estimator evaluation and the final exact policy-comparison step
(solving a 2187x2187 linear system instead of 192x192) both do scale
with |S|, and neither was timed end-to-end in this verification (only
the state enumeration and the exact LP solve were). Budget noticeably
more time than prior K=1 runs at the same T=15000, and treat the
per-seed runtime as genuinely unknown until the first seed completes --
don't assume it will match the K=1 timings.

CANONICAL MODEL, matching the specified formula exactly:
    V_hat = theta^(0)
      + sum_{a=1}^{L} theta^(h_a) * h_{0,a} * n_{0,a,t}
      + theta^(sigma) * sum_{p=1}^{P} max(0, mu_p*tau_t - sum_a n_{p,a,t})
      + theta^(Delta) * |N_1/mu_1 - N_2/mu_2|
      + theta^(r) * (C_dep*n_{0,1,t} + C_lab*sum_p n_{p,1,t})
B = L_AGE + 4 = 6.

Usage
-----
Just open this file in VS Code and click "Run Python File" (top right) or
press Ctrl+F5 -- no terminal, no arguments needed. Edit the two variables
below first if you want a different seed count:

    CONFIG_NAME = 'inputs_evaluate_approximation_L2_canonical'
    SEEDS       = [0, 1, 2, 3]
"""

