def _ensure_bootstrap_files():
    project_root = os.path.dirname(os.path.abspath(__file__))
    for rel_path, b64_chunks in _BOOTSTRAP_FILES.items():
        full_path = os.path.join(project_root, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        content = base64.b64decode(b64_chunks)
        already_matched = (os.path.exists(full_path) and
                           open(full_path, 'rb').read() == content)
        with open(full_path, 'wb') as f:
            f.write(content)
        if not already_matched:
            print(f"[bootstrap] wrote/updated: {rel_path} ({len(content)} bytes)")
    print()

def parse_seeds(arg):
    """Accepts either a count ('5' -> [0,1,2,3,4]) or an explicit
    comma-separated list ('0,1,2,7,12')."""
    if ',' in arg:
        return [int(x) for x in arg.split(',')]
    return list(range(int(arg)))


def run_one(config_name, seed):
    print(f"\n{'='*70}\nRunning {config_name}, seed={seed}\n{'='*70}")
    result = subprocess.run(
        [sys.executable, "evaluate_approximation.py", config_name, str(seed)],
        cwd=os.path.dirname(os.path.abspath(__file__)) or ".",
    )
    if result.returncode != 0:
        print(f"WARNING: seed={seed} exited with code {result.returncode} -- "
              f"skipping it in the aggregate.")
        return False
    return True


def find_summaries(config_name, seeds):
    """Load comparison_summary.json for exactly the (config, seed) pairs
    just run, matched via each folder's own recorded config_module/run_seed
    fields rather than by guessing folder-name patterns.

    Deduplicates by seed: if multiple folders match the same (config_name,
    run_seed) pair -- e.g. leftovers from an earlier test run with the same
    seed -- only the most recently modified one is kept. Without this, old
    and new runs of the same seed silently both entered the aggregate,
    inflating the seed count and corrupting the mean/std (confirmed: this
    is exactly what produced 'Seeds: [0, 0, 1, 1, 2, 2, 3, 3]' instead of
    [0, 1, 2, 3] in an earlier run)."""
    candidates = {}   # run_seed -> (mtime, summary_dict)
    for folder in sorted(glob.glob("./results/*evaluate_approximation_*/")):
        path = os.path.join(folder, "comparison_summary.json")
        if not os.path.exists(path):
            continue
        with open(path) as f:
            s = json.load(f)
        if s.get('config_module') != config_name or s.get('run_seed') not in seeds:
            continue
        s['_folder'] = folder
        mtime = os.path.getmtime(path)
        seed = s['run_seed']
        if seed not in candidates or mtime > candidates[seed][0]:
            candidates[seed] = (mtime, s)
    return [s for _, s in candidates.values()]


def print_aggregate(config_name, summaries):
    print("\n" + "=" * 70)
    print(f"MULTI-SEED AGGREGATE — {config_name}  ({len(summaries)} seeds)")
    print("=" * 70)

    if not summaries:
        print("No matching results found.")
        return

    seeds = sorted(s['run_seed'] for s in summaries)
    agree = np.array([s['policy_agreement_pct'] for s in summaries])
    mean_gap = np.array([s['relative_gap_mean_pct'] for s in summaries])
    max_gap = np.array([s['relative_gap_max_pct'] for s in summaries])

    print(f"Seeds: {seeds}\n")
    print(f"{'metric':<28}{'mean':>10}{'std':>10}{'min':>10}{'max':>10}")
    for label, arr in [('Policy agreement %', agree),
                       ('Mean relative gap %', mean_gap),
                       ('Max relative gap %', max_gap)]:
        print(f"{label:<28}{arr.mean():>10.2f}{arr.std():>10.2f}"
              f"{arr.min():>10.2f}{arr.max():>10.2f}")

    print(f"\nPer-seed policy agreement: "
          f"{dict(zip(seeds, np.round(agree, 2)))}")
    print("=" * 70)
    print("\nInterpretation: if std is large relative to the mean, a single")
    print("run's number (like the one you looked at before) is NOT a")
    print("reliable read on approximation quality by itself -- report the")
    print("mean +/- std across seeds instead, and treat any one run as one")
    print("draw from this distribution, not as the answer.")


def feature_names_for(n_labs, l_age):
    """Same feature-set logic as evaluate_approximation.py's own copy of
    this (which mirrors classes/alp_evaluate_approximation.py's canonical
    _phi_raw), duplicated here since run_multiseed.py launches
    evaluate_approximation.py as a subprocess rather than importing it."""
    names = ['const'] + [f'depot_age{a+1}' for a in range(l_age)]
    names += ['lab_shortfall_agg']
    if n_labs >= 2:
        names += ['imbalance', 'exp_risk']
    else:
        names += ['exp_risk']
    return names


def plot_combined_theta_convergence(summaries, config_name):
    """Overlay every seed's theta_bar trajectory on ONE set of charts (one
    subplot per feature, each seed a different line) -- this is the
    at-a-glance comparison across seeds that individual per-seed PNGs
    (already written by evaluate_approximation.py itself) don't give you
    directly. Loads Thetabar_trajectory from each seed's model_param.json."""
    if not summaries:
        print("\nNo summaries to plot theta convergence for.")
        return

    trajectories = {}
    n_labs = l_age = None
    for s in summaries:
        folder = s['_folder']
        mp_path = os.path.join(folder, 'model_param.json')
        cfg_path = os.path.join(folder, 'inputs.json')
        if not os.path.exists(mp_path):
            continue
        with open(mp_path) as f:
            mp = json.load(f)
        if 'Thetabar_trajectory' not in mp:
            print(f"\n[combined convergence plot] {folder} has no "
                  f"Thetabar_trajectory saved (older evaluate_approximation.py?) "
                  f"-- skipping it.")
            continue
        trajectories[s['run_seed']] = np.array(mp['Thetabar_trajectory'])
        if os.path.exists(cfg_path) and (n_labs is None or l_age is None):
            with open(cfg_path) as f:
                inst_cfg = json.load(f)
            n_labs = inst_cfg.get('N_LABS')
            l_age = inst_cfg.get('L_AGE')

    if not trajectories:
        print("\nNo Thetabar_trajectory data found across any seed -- "
              "can't build the combined convergence plot.")
        return

    if n_labs is None or l_age is None:
        # comparison_summary.json doesn't carry N_LABS/L_AGE directly in
        # every version -- fall back to inferring B and using generic names.
        B = next(iter(trajectories.values())).shape[1]
        names = [f'theta_{b}' for b in range(B)]
    else:
        names = feature_names_for(n_labs, l_age)

    B = next(iter(trajectories.values())).shape[1]
    seeds_sorted = sorted(trajectories.keys())

    n_cols = 2
    n_rows = (B + n_cols - 1) // n_cols
    fig, axes = plt.subplots(n_rows, n_cols, figsize=(12, 3.2 * n_rows))
    axes = np.atleast_1d(axes).ravel()

    for b in range(B):
        ax = axes[b]
        for seed in seeds_sorted:
            traj = trajectories[seed]
            ax.plot(range(traj.shape[0]), traj[:, b], label=f'seed={seed}')
        ax.set_title(names[b] if b < len(names) else f'theta_{b}')
        ax.set_xlabel('PSMD iteration t')
        ax.set_ylabel('theta_bar')
        ax.legend(fontsize=7)
        ax.grid(True, alpha=0.4)

    for b in range(B, len(axes)):
        axes[b].axis('off')

    plt.suptitle(f'Theta convergence across all seeds -- {config_name}')
    plt.tight_layout()
    fname = f'theta_convergence_combined_{config_name}.png'
    plt.savefig(fname, dpi=150)
    plt.close(fig)
    print(f"\nCombined cross-seed convergence plot written: {fname}")


if __name__ == "__main__":
    # Anchor to the script's own directory BEFORE anything else -- every
    # relative path used below (results/ glob, PNG filenames) is relative
    # to whatever the process's current working directory happens to be,
    # which is NOT necessarily this script's own location (e.g. depends on
    # how VS Code launched it). Confirmed directly: without this, running
    # from a different cwd makes find_summaries() silently find zero
    # results even though evaluate_approximation.py's subprocess calls
    # (which DO set their own cwd explicitly) wrote them correctly -- the
    # aggregate prints "0 seeds" and the combined convergence plot is
    # silently never created, with no error at all.
    os.chdir(os.path.dirname(os.path.abspath(__file__)) or ".")

    _ensure_bootstrap_files()

    args = [a for a in sys.argv[1:] if not a.startswith('-')]
    config_name = args[0] if len(args) >= 1 else CONFIG_NAME
    seeds = parse_seeds(args[1]) if len(args) >= 2 else SEEDS

    print(f"Config: {config_name}")
    print(f"Seeds:  {seeds}")

    ok_seeds = []
    for seed in seeds:
        if run_one(config_name, seed):
            ok_seeds.append(seed)

    summaries = find_summaries(config_name, ok_seeds)
    print_aggregate(config_name, summaries)
    plot_combined_theta_convergence(summaries, config_name)
